import { S3Client, PutObjectCommand, DeleteObjectCommand, GetObjectCommand } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import type { Config } from "../config.js";
import { withContext, type Db } from "../db/index.js";

export interface ArtifactStore {
  put(key: string, bytes: Uint8Array, filename: string): Promise<void>;
  download(key: string, filename: string): Promise<string>;
  delete(key: string): Promise<void>;
}

/** Private bucket, fixed keys generated by the server, short-lived download links.
 * HTML is always downloaded as octet-stream, never executed on the app origin. */
export function artifactStore(config: Config): ArtifactStore | undefined {
  if (!config.ARTIFACT_BUCKET) return undefined;
  const client = new S3Client({ region: config.ARTIFACT_REGION, endpoint: config.ARTIFACT_ENDPOINT, forcePathStyle: config.ARTIFACT_PATH_STYLE,
    requestChecksumCalculation: "WHEN_REQUIRED", responseChecksumValidation: "WHEN_REQUIRED" });
  const Bucket = config.ARTIFACT_BUCKET;
  const disposition = (name: string) => `attachment; filename="${name.replace(/[^a-z0-9._-]/gi, "_")}"`;
  return {
    async put(Key, Body, filename) { await client.send(new PutObjectCommand({ Bucket, Key, Body, ContentLength: Body.byteLength,
      ContentType: "application/octet-stream", ContentDisposition: disposition(filename) }), { abortSignal: AbortSignal.timeout(30000) }); },
    async download(Key, filename) { return getSignedUrl(client, new GetObjectCommand({ Bucket, Key, ResponseContentType: "application/octet-stream", ResponseContentDisposition: disposition(filename) }), { expiresIn: 300 }); },
    async delete(Key) { await client.send(new DeleteObjectCommand({ Bucket, Key }), { abortSignal: AbortSignal.timeout(30000) }); },
  };
}

export async function cleanupArtifacts(db: Db, store: ArtifactStore) {
  const expired = await db.raw<{ id: string; org_id: string; object_key: string }>("select * from qa_expired_artifacts(100)");
  for (const artifact of expired) {
    // Delete the object first; a failed deletion is retried, never silently orphaned.
    await store.delete(artifact.object_key);
    await withContext(db, { orgId: artifact.org_id }, (q) => q("delete from artifacts where id = $1 and (expires_at <= now() or run_id is null)", [artifact.id]));
  }
  return expired.length;
}

export function startArtifactCleanup(db: Db, store: ArtifactStore | undefined) {
  if (!store) return () => {};
  let busy = false;
  const timer = setInterval(async () => {
    if (busy) return;
    busy = true;
    try { await cleanupArtifacts(db, store); } catch { console.error("[artifacts] Retention cleanup failed; will retry"); }
    finally { busy = false; }
  }, 60000);
  timer.unref(); return () => clearInterval(timer);
}
